function processUbuntuAdvisories(inputJson) {
    let result = {};

    for (let recommendation of inputJson["recommendations"]) {
        let hostName = recommendation["environment"]["host_name"];
        let patch_commands = [];

        for (let severity of ["critical", "high", "medium", "low"]) {
            for (let patch of recommendation["patches"][severity]) {
                if (patch["metadata"] && patch["metadata"]["correction_commands"]) {
                    patch_commands.push(...patch["metadata"]["correction_commands"]);
                }
            }
        }

        patch_commands = Array.from(new Set(patch_commands));
        result[hostName] = patch_commands;
    }

    return result;
};

function getAuthList(patches, authList) {
    const ips = new Set(Object.keys(patches));
    return authList.filter(entry => entry.host.some(ip => ips.has(ip))).map(entry => entry.auth);
}

$patchesToApply = processUbuntuAdvisories($input_json_data);
$auth_list = getAuthList($patchesToApply, $GetConfigData.result.config);

$auth_host_map = $GetConfigData.result.config.reduce((map, item) => {
    map[item.auth] = item.host;
    return map;
}, {})
